import java.util.*;

public class Main {
    static String prefix(String environment, String file) {
        if (!environment.equals("-")) return environment;
        if (!file.equals("-")) return file;
        return "Hello";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String environment = sc.nextLine();
        String file = sc.nextLine();
        String name = sc.nextLine();
        boolean available = Boolean.parseBoolean(sc.nextLine());
        if (!available) {
            System.out.println("503 SERVICE_UNAVAILABLE");
        } else if (name.isBlank()) {
            System.out.println("400 NAME_REQUIRED");
        } else {
            System.out.println("200 " + prefix(environment, file) + ", " + name.trim());
        }
    }
}

