import java.util.*;

public class Main {
    static String policy(String environment, String endpoint) {
        if (endpoint.equals("env")) return "DENY";
        if (environment.equals("public")) {
            return endpoint.equals("health") || endpoint.equals("info") ? "ALLOW" : "DENY";
        }
        return switch (endpoint) {
            case "health", "info", "metrics" -> "ALLOW";
            case "loggers" -> "ADMIN_ONLY";
            default -> "DENY";
        };
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String environment = sc.nextLine();
        String endpoint = sc.nextLine();
        System.out.println(endpoint + ":" + policy(environment, endpoint));
    }
}
